"""Tests for catalog pagination helpers."""

from catalog.pagination import paginate, total_pages


def test_paginate_with_four_per_page_returns_four_items():
    """With 4 items per page, a page must show exactly 4 items."""
    items = list(range(1, 11))
    result = paginate(items, page=1, per_page=4)
    assert result == [1, 2, 3, 4]


def test_paginate_last_page_includes_final_item():
    """The final page must include its last item, not drop it."""
    items = list(range(1, 11))
    result = paginate(items, page=3, per_page=4)
    assert result == [9, 10]


def test_paginate_never_excludes_items():
    """No items should ever be missing from the listing."""
    items = list(range(1, 11))
    for page in range(1, 3):
        result = paginate(items, page=page, per_page=4)
        assert len(result) == 4
        assert all(item in result for item in items)


def test_total_pages_with_exact_multiple():
    """Total pages calculation remains correct for exact multiples."""
    assert total_pages(8, per_page=4) == 2


def test_total_pages_with_remainder():
    """Total pages calculation remains correct with a remainder."""
    assert total_pages(10, per_page=4) == 3


def test_paginate_raises_on_invalid_page():
    """Invalid page numbers must raise a ValueError."""
    items = list(range(1, 11))
    try:
        paginate(items, page=0, per_page=4)
    except ValueError:
        pass
    else:
        raise AssertionError("Expected ValueError for page < 1")


def test_paginate_raises_on_invalid_per_page():
    """Invalid per_page values must raise a ValueError."""
    items = list(range(1, 11))
    try:
        paginate(items, page=1, per_page=0)
    except ValueError:
        pass
    else:
        raise AssertionError("Expected ValueError for per_page < 1")

import pytest
from tagger.notes import add_tag


def test_tags_are_independent_between_notes():
    note1 = {"id": "note1", "content": "First note"}
    note2 = {"id": "note2", "content": "Unrelated note"}

    add_tag(note1, "errand", [])

    # The unrelated note must not inherit the tag from note1.
    assert "errand" not in note2.get("tags", [])
    assert note2.get("tags") == []

    # The tagged note must still have its own tag list.
    assert note1.get("tags") == ["errand"]


def test_tag_is_not_duplicated():
    note = {"id": "note", "content": "Note"}

    add_tag(note, "errand", [])
    add_tag(note, "errand", [])

    assert note.get("tags") == ["errand"]

import pytest

from tagger.notes import add_tag


def test_tags_are_independent_between_notes():
