def test_add_tag_returns_updated_tags():
    note = {"id": 1}

    result = add_tag(note, "errand", [])

    assert result == ["errand"]
    assert note["tags"] == ["errand"]


def test_add_tag_does_not_duplicate_existing_tag():
    note = {"id": 1}

    add_tag(note, "errand", [])
    add_tag(note, "errand", [])

    assert note["tags"] == ["errand"]
    assert len(note["tags"]) == 1

